import React, { useEffect , useState } from 'react'
import pass_photo from '../Assets/pass_photo.jpg';
import pass_photo3 from '../Assets/pass_photo3.jpg';
import {Facebook, Github, Instagram, Linkedin, Phone, X} from 'lucide-react'
import axios from 'axios';
// import Resume from './Resume.pdf'


const Home = ({ data }) => {

    const [userData , setUserData] = useState([]);

    
    

    useEffect(() => {
      setUserData(data);
      console.log(userData);
    }, [data]);

      const link_icons = {

      "Linkedin": <Linkedin/>,
      "Github": <Github/>,
      "Instagram": <Instagram/>,
      "Phone": <Phone/>,
      "X": <X/>,
      "Facebook" :<Facebook  />


      }

   

  return <>
  <div className='w-[98%] h-[700px] flex mx-auto mt-20  flex justify-evenly items-center gap-12 '>
    <div>
         <img src={pass_photo3} alt="my_photo"    className=' w-full h-[20rem] border border-2 rounded-full '/>
    </div>
    <div className='flex flex-col gap-4 max-w-[40rem] '>
        <h1>Hi, I'm <br /> {userData[0]?.home?.name} </h1>
        <h2 className='text-gray' > {userData[0]?.home?.role} </h2>
        <p>{userData[0]?.home?.description}</p>

        <div className='flex flex-col gap-12' >
        <div className='flex flex-row gap-4 mt-4 w-full' >
          <button className='border-2 px-2 py-2 rounded border-text w-full'><a href="/Resume.pdf" target='_blank'> <p> Resume </p></a> </button>
          <button className='border-2 px-2 py-2 rounded border-text w-full'> <a href="/"> <p>Contact Me </p></a></button>
        </div>
        <div>
          

            {userData[0]?.links?.map((link,index)=>(
                  <ul className='flex flex-row gap-16 ml-4'>
                    <li><a href="https://www.linkedin.com/in/sathish-kumar-r-514070312/" target='_blank'>{link_icons}</a></li>
          </ul>
            ))}
         
        </div>
        </div>
    </div>
  </div>
  </>
}

export default Home;
